struct  _RpcReqAlarmSet
{
  ProtobufCMessage base;
  uint32_t year;
  uint32_t month;
  uint32_t day;
  uint32_t hour;
  uint32_t minute;
  uint32_t second;
  uint32_t index;
  /*
   * mode 位掩码（与 SDK alarm 一致）：
   *   0x00 = ONCE
   *   0x01 = EVERY_DAY
   *   0x02..0x80 = 周一..周日（可按位或组合）
   */
  uint32_t mode;
  /*
   * 闹钟开关：0 = 未指定（兼容旧主机，按启用处理），1 = 启用，2 = 关闭（保留槽位仅停用）
   */
  uint32_t sw;
};
