struct  _RpcReqBtDisconnect
{
  ProtobufCMessage base;
  /*
   * true  = 只断开当前连接, 保留配对信息(link key / 设备记录), 下次可直接回连
   * false = 断开并解绑(删 link key + 删设备记录), 与本字段出现之前的行为一致
   * 特意取 keep_bond 而不是 unbind: proto3 不发默认值, 旧固件收到新主机的包时
   * 本字段一律缺省, 按 false 走解绑 —— 和它本来的行为撞在同一个语义上。反过来
   * 定义成 unbind 的话, 旧固件会把"只断开"当成解绑执行, 而且不报错。
   */
  protobuf_c_boolean keep_bond;
};
