/*
 * ---- 写入会话 ----
 * 下发的一律是**设备绑定加密包**: 服务器按目标设备的蓝牙 MAC 封装, 换台机器
 * 解不开。每份容器的形态是 [header 明文][body 密文][key_id 1][保留 3][salt 16][tag 16], header
 * 不加密, 所以固件收到第一片就能读出 total_size / num_states 提前拒。
 * 一次会话可以连续写多份 —— 主机把 N 份加密包首尾相接发过来(不用自己算对齐,
 * 每份的长度就是它 header 里的 total_size + 36)。固件全程收在 RAM 里,
 * WriteEnd 时整批解封、把明文挤成连续镜像, 校验都过了才落到目标区域。
 * 同一时刻只允许一个会话。
 * 因此 WriteBegin 不再擦除 FLASH: 解封失败、中止、断线, 目标区域一个字节都
 * 没被碰过, 老词表照常能用。
 */
struct  _RpcReqAsrFstWriteBegin
{
  ProtobufCMessage base;
  /*
   * 写到哪个区域(BUILTIN 会被拒)
   */
  AsrFstArea area;
  /*
   * N 份加密包拼起来的总字节数(含每份 36 字节尾巴)
   */
  uint32_t total_size;
  /*
   * 本次写入几份容器
   */
  uint32_t group_count;
  /*
   * 主机声明的最大状态数, 用于提前拒绝
   */
  uint32_t declared_max_states;
};
#define RPC__REQ__ASR_FST_WRITE_BEGIN__INIT \
 { PROTOBUF_C_MESSAGE_INIT (&rpc__req__asr_fst_write_begin__descriptor) \
    , ASR_FST_AREA__ASR_FST_AREA_BUILTIN, 0, 0, 0 }


struct  _RpcRespAsrFstWriteBegin
{
  ProtobufCMessage base;
  int32_t resp;
  uint32_t detail;
  /*
   * 该区域容量, 便于主机提前判断放不放得下
   */
  uint32_t capacity;
  /*
   * 单片 payload 上限
   */
  uint32_t max_chunk;
  /*
   * 解码器的状态数上限
   */
  uint32_t max_states;
};
