/*
 * 收尾: 整批解封(AES-128-CTR 解密 + AES-CMAC 校验), 再扫描该区域逐个容器做
 * 完整校验(含 CRC32) —— 两层互相独立, CMAC 管"是不是发给这台机器的、有没有被
 * 改过", CRC32 管"解出来的数据对不对"。
 * 认下的组数与 group_count 对不上就算失败。
 * 解封失败(密钥不对/错设备/被篡改/发的是明文包)时 resp = RPC_ERR(-1),
 * detail = FST_ERR_DECRYPT(14); 和数据传坏了(RPC_ERR_INVALID_ARG)分得开 ——
 * 前者要换包, 后者重传就行。
 */
struct  _RpcReqAsrFstWriteEnd
{
  ProtobufCMessage base;
  /*
   * true 立即切到本次写入的语法
   */
  protobuf_c_boolean apply_now;
  /*
   * apply_now 时切到哪一组
   */
  uint32_t apply_index;
};
#define RPC__REQ__ASR_FST_WRITE_END__INIT \
 { PROTOBUF_C_MESSAGE_INIT (&rpc__req__asr_fst_write_end__descriptor) \
    , 0, 0 }


