{
  ProtobufCMessage base;
  int32_t resp;
  uint32_t detail;
  /*
   * 实际认下几组
   */
  uint32_t accepted;
  /*
   * 每组的 id/词数/状态数, 便于主机对账
   */
  size_t n_groups;
  AsrFstGroup **groups;
};
#define RPC__RESP__ASR_FST_WRITE_END__INIT \
 { PROTOBUF_C_MESSAGE_INIT (&rpc__resp__asr_fst_write_end__descriptor) \
    , 0, 0, 0, 0,NULL }


